//! Vectors for `wf_units.h`, generated by `scripts/cpp_vectors/frame_wf_units_vectors.cpp`.

use std::collections::HashMap;

use fp_core::frame::wf_frame::WfShapeLookup;
use fp_core::frame::wf_units::{wf_shape_of_units, wf_units_fault, WfUnit};

const VECTORS: &str = include_str!("../../fixtures/frame_wf_units_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn f_str(x: fp_core::field::ext::F) -> String {
    format!("{:016x}", x.0)
}

fn lookup_str(l: &WfShapeLookup) -> String {
    let weights: Vec<String> = l.lookup.digit_weight.iter().map(|x| f_str(*x)).collect();
    let bound = if l.lookup.first_bound.is_empty() {
        String::from("-")
    } else {
        l.lookup
            .first_bound
            .iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(",")
    };
    let entries: Vec<String> = l
        .entries
        .iter()
        .map(|e| format!("{}:{}:{}:{}", e.first_place, e.first_row, e.places, e.stride))
        .collect();
    format!(
        "name={} d={} mu={} live={} weights={} offset={} padding={} first_bound={} entries={} log_rows_apart={}",
        l.lookup.name,
        l.lookup.d,
        l.lookup.mu,
        l.lookup.live,
        weights.join(","),
        f_str(l.lookup.offset),
        f_str(l.lookup.padding_key),
        bound,
        entries.join(";"),
        l.log_rows_apart
    )
}

/// The cases, in the tool's order.
fn cases() -> Vec<(&'static str, u32, u64, u64, Vec<WfUnit>)> {
    let mixed = vec![
        WfUnit { first_row: 0, rows: 80, digits: 2 },
        WfUnit { first_row: 80, rows: 16, digits: 4 },
        WfUnit { first_row: 96, rows: 4, digits: 2 },
    ];
    vec![
        ("mixed", 11, 100, 100, mixed.clone()),
        ("mixed_k8", 8, 100, 100, mixed.clone()),
        ("mixed_k9", 9, 100, 100, mixed.clone()),
        (
            "tail_bytes",
            11,
            108,
            108,
            vec![
                WfUnit { first_row: 0, rows: 80, digits: 2 },
                WfUnit { first_row: 80, rows: 16, digits: 4 },
                WfUnit { first_row: 96, rows: 10, digits: 2 },
            ],
        ),
        ("four_digits_only", 11, 40, 40, vec![WfUnit { first_row: 0, rows: 40, digits: 4 }]),
        ("empty", 11, 100, 100, vec![]),
        ("odd_ranged", 11, 100, 99, mixed.clone()),
        ("ranged_more", 11, 90, 100, mixed.clone()),
        (
            "matrix_big",
            11,
            1u64 << 40,
            1u64 << 40,
            vec![WfUnit { first_row: 0, rows: 1u64 << 40, digits: 2 }],
        ),
        ("digit_three", 11, 100, 100, vec![WfUnit { first_row: 0, rows: 80, digits: 3 }]),
        ("rows_zero", 11, 100, 100, vec![WfUnit { first_row: 0, rows: 0, digits: 2 }]),
        ("rows_odd", 11, 100, 100, vec![WfUnit { first_row: 0, rows: 81, digits: 2 }]),
        (
            "gap",
            11,
            100,
            100,
            vec![
                WfUnit { first_row: 0, rows: 80, digits: 2 },
                WfUnit { first_row: 82, rows: 18, digits: 2 },
            ],
        ),
        (
            "overlap",
            11,
            100,
            100,
            vec![
                WfUnit { first_row: 0, rows: 82, digits: 2 },
                WfUnit { first_row: 80, rows: 20, digits: 2 },
            ],
        ),
        (
            "beyond",
            11,
            100,
            100,
            vec![
                WfUnit { first_row: 0, rows: 80, digits: 2 },
                WfUnit { first_row: 80, rows: 22, digits: 2 },
            ],
        ),
    ]
}

#[test]
fn wf_units_match_the_cpp_reference() {
    let mut lines = VECTORS.lines();
    for (name, k_col, matrix_rows, ranged_rows, units) in cases() {
        let line = lines.next().unwrap();
        let head = fields(line);
        assert_eq!(head["name"], name);
        let expected = wf_units_fault(matrix_rows, ranged_rows, &units);
        let got = line.split_once("fault=").unwrap().1.split(" k_col=").next().unwrap();
        assert_eq!(got, expected.unwrap_or("-"), "{}: fault", name);
        if expected.is_some() {
            continue;
        }
        let count_line = fields(lines.next().unwrap());
        assert_eq!(count_line["name"], name);
        let count: usize = count_line["count"].parse().unwrap();
        let shape = wf_shape_of_units(k_col, matrix_rows, ranged_rows, &units);
        assert_eq!(shape.lookups.len(), count, "{}: lookup count", name);
        for (i, l) in shape.lookups.iter().enumerate() {
            let line = lines.next().unwrap();
            assert!(line.starts_with("LOOKUP "), "{}: {}", name, line);
            assert_eq!(line.strip_prefix("LOOKUP ").unwrap(), lookup_str(l), "{}: lookup {}", name, i);
        }
    }
    assert!(lines.next().is_none(), "extra vector lines");
}
